  ('todos-santos-mexico', '10S', 'Todos Santos', 'Mexico', 'A Pueblo Mágico of galleries and mango orchards', 'live', 'verified', 'tropicalBeach', 'Baja California Sur (Los Cabos & La Paz)', '{"expedition","culture","wellness","ocean"}', '{}', '{"essential","comfort","premier","luxury"}', null, null, '{"key_facts":["Designated Pueblo Mágico art town with numerous galleries (Source: loscabosguide.com, Accessed 2026-07-04)","Hotel California is the famous landmark; the Eagles'' band denies any direct link (Source: incabotravel.com, Accessed 2026-07-04)","Most beaches are NOT safe to swim due to strong rip currents/backwash; Cerritos is the gentlest for swimming (Source: amyrextodossantos.com, Accessed 2026-07-04)","San Pedrito has powerful currents unsuitable for swimming — advanced surf only (Source: tripadvisor.com, Accessed 2026-07-04)","Whale season late-Dec–Apr (best Jan–Mar), gray + humpback, Magdalena Bay extensions (Source: todossantosvillarentals.com, Accessed 2026-07-04)"],"safety":{"emergency":"911","hospital":"No major hospital in town; serious cases to Los Cabos (H+ Los Cabos 24/7 ER, AmeriMed, Blue Medical/BlueNet) or La Paz — ~1-hr transfer; air-evac to US for critical cases","malaria":"none","yellow_fever":"not required","fcdo":{"posture":"AREA-RESTRICTED","quotes":[],"url":"https://www.gov.uk/foreign-travel-advice/mexico","read":"2026-09-04T12:02:56Z","page_updated":"2026-09-04T00:25:51+01:00","source_country":"mexico","quotes_note":"not extracted by the join — a restricted-area clause is quoted by a human, never composed"},"posture":"book-freely","fcdo_zones":[{"name":"The city of Tijuana, in Baja California","lvl":3,"posture":"all-but-essential","except":["airside transit through Tijuana airport","the Cross Border Xpress bridge linking the airport across the border","federal toll road 1D and the Via Rápida through Tijuana to the border"]},{"name":"The city of Tecate in Baja California, including roads between Tijuana and Tecate","lvl":3,"posture":"all-but-essential"},{"name":"The state of Chihuahua","lvl":3,"posture":"all-but-essential","except":["the city of Chihuahua","the border crossing in Ciudad Juárez via federal toll road 45","federal toll road 45D between Chihuahua and Ciudad Juárez","the Copper Canyon rail route and the towns immediately on it, including Creel","the road from Creel via San Juanito to San Pedro","state highway 16 from San Pedro to Chihuahua"],"note":"The advisory also covers the areas south-west of road 45D."},{"name":"The state of Sinaloa","lvl":3,"posture":"all-but-essential","except":["the cities of Los Mochis and Mazatlán","road 32 between El Fuerte and Los Mochis","the 15D federal toll road running the length of the state","the Copper Canyon rail route to and from Los Mochis and El Fuerte, and the towns immediately on it"]},{"name":"The state of Tamaulipas","lvl":3,"posture":"all-but-essential","except":["the border crossing at Nuevo Laredo via federal toll road 85D from Monterrey","federal highways 80, 81 and 85 between Tampico, Ciudad Victoria and Magueyes","the area of Tamaulipas south of those highways"]},{"name":"The state of Zacatecas","lvl":3,"posture":"all-but-essential"},{"name":"In Guanajuato: the areas south-west of road 45D","lvl":3,"posture":"all-but-essential","note":"FCDO advises against all but essential travel to the areas south-west of road 45D. (San Miguel de Allende and Guanajuato City sit outside this area.)"},{"name":"The state of Michoacán","lvl":3,"posture":"all-but-essential","except":["the city of Morelia via federal toll roads 15D, 126 and 43","toll road 48D between Morelia and its airport","the town of Pátzcuaro via toll roads 14D and 15 from Morelia, and boat trips on Lake Pátzcuaro","Federal Highway 15D"]},{"name":"In Jalisco: the areas south and south-west of Lake Chapala to the Colima border","lvl":3,"posture":"all-but-essential","note":"Thirty-nine named municipalities, including Autlán de Navarro, Sayula, Tapalpa, Cocula and Villa Corona — the advisory lists each by name."},{"name":"In Jalisco: eleven northern municipalities","lvl":3,"posture":"all-but-essential","note":"Bolaños, Chimaltitán, Colotlán, Hostotipaquillo, Huejúcar, Huequilla el Alto, Mezquitic, San Martín de Bolaños, Santa María de los Ángeles, Totatiche and Villa Guerrero."},{"name":"The state of Colima","lvl":3,"posture":"all-but-essential","except":["the city of Manzanillo by sea, or by air via Manzanillo-Costalegre International Airport","direct travel via road 200 from that airport to Manzanillo"]},{"name":"The state of Guerrero, including the city of Acapulco","lvl":3,"posture":"all-but-essential","except":["the town of Zihuatanejo/Ixtapa accessed by air"]},{"name":"Within 40km of the Guatemalan border, from the Pacific Coast up to and including the Gracias a Dios crossing","lvl":3,"posture":"all-but-essential"},{"name":"Federal Highway 199 between Rancho Nuevo, outside San Cristóbal de las Casas, and the Chancalá junction outside Palenque","lvl":3,"posture":"all-but-essential","note":"The restriction is the highway segment, not the towns at either end."}]},"timing":{"peak":"November–April (dry, whale-watching, winter N-swell surf)","shoulder":"May–June & October","green":"July–September into early October (hot, hurricane/chubasco, summer S-swell)","booking_lead":"3–5+ months for peak boutique inventory (small supply)","off_season_specials":"Green-season summer surf + desert-wellness value; disclose storm risk + insurance","event_peaks":"Christmas/New Year, Semana Santa, whale Jan–Mar, surf winter N-swell Nov–Mar + summer S-swell Jun–Sep","fire_date":"Late summer/early fall for Nov–Apr peak; late spring for green-season surf/wellness"},"jewels":[{"name":"Gallery walk + Hotel California","status":"future","hook":"Pueblo Mágico galleries + the mythic Hotel California","bookable_category":"free stroll / dining","tier":"essential","source":"https://incabotravel.com/uncover-todos-santos-hotel-california-myths-facts-must-visit-spots (Accessed 2