, gentlest first-swim","when":"dry season Nov-Apr","commission":"DMC + Viator affiliate (entry non-commissionable)","wells":["activities"],"wells_basis":"derived from name/blurb/hook","si_all":["expedition"],"shelf_fit":{"culinary":"destination","culture":"destination","expedition":"primary"},"commission_lane":["DMC","affiliate"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Cenote Suytun (iconic light-beam)","status":"live","tier":"essential","bookable":"entry ~250 MXN (230 online) + combo tour","source":"https://www.dreambigtravelfarblog.com/blog/cenote-suytun","timing":"dry season Nov-Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"the region''s most photographed cenote — a single beam of light falls on a central stone platform","si":"expedition","blurb":"the region''s most photographed cenote — a single beam of light falls on a central stone platform","when":"dry season Nov-Apr","commission":"DMC + Viator affiliate","wells":[],"wells_basis":"text supports no Well — needs a human read","si_all":["expedition"],"shelf_fit":{"culinary":"destination","culture":"destination","expedition":"primary"},"commission_lane":["DMC","affiliate"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Cenote Oxman (hacienda sinkhole + rope swing)","status":"live","tier":"essential","bookable":"150 MXN (350 w/ pool + lunch)","source":"https://cenotefinder.com/cenotes-in-mexico/valladolid-cenotes/","timing":"dry season Nov-Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"deep sinkhole draped in roots on a working hacienda, pool + restaurant, quieter","si":"expedition","blurb":"deep sinkhole draped in roots on a working hacienda, pool + restaurant, quieter","when":"dry season Nov-Apr","commission":"DMC + Viator affiliate","wells":["eat"],"wells_basis":"derived from name/blurb/hook","si_all":["culinary","expedition"],"shelf_fit":{"culinary":"evidenced","culture":"destin