  ('valle-de-guadalupe-mexico', '10S', 'Valle de Guadalupe, Mexico', 'Mexico', 'A Grenache poured at the vine that grew it', 'live', 'verified', 'restaurant', 'Baja California (Valle de Guadalupe & Ensenada)', '{"culinary","expedition"}', '{}', '{"essential","comfort","premier","ultra"}', null, null, '{"key_facts":["Mexico''s premier wine country — 100+ wineries along the Ruta del Vino, producing >90% of Mexican wine.","Baja Med farm-to-table anchors: Deckman''s en el Mogor (Michelin), Fauna, Corazón de Tierra, Finca Altozano.","Fiestas de la Vendimia (August) is the peak: 80+ wineries, 160+ labels, paella competition, pairing dinners.","Design wine-lodges: Banyan Tree Veya (30 villas, on-site Grenache winery), Encuentro/Endémico, Bruma."],"safety":{"emergency":"911","trauma":"Ensenada/Tijuana → San Diego US cross-border evacuation (US-standard trauma care) — a structural cross-border advantage","drink_driving":"always a designated driver / guided wine tour — never self-drive the tasting circuit","rural_road":"Hwy 3 + winery access roads are rural, partly unlit; daylight transfers only, no rural night driving","water":"bottled/filtered","air_access_verified":"Tijuana International (TIJ) via Cross Border Xpress (CBX) pedestrian bridge from San Diego (Otay Mesa), then ~1–1.5 hr drive on Hwy 3; or San Ysidro/Otay Mesa land crossing; Ensenada as coastal gateway. San Diego → Valle ~1h52m + border.","source":"https://www.gov.uk/foreign-travel-advice/mexico","accessed":"2026-07-07","fcdo":{"posture":"AREA-RESTRICTED","quotes":[],"url":"https://www.gov.uk/foreign-travel-advice/mexico","read":"2026-09-04T12:02:56Z","page_updated":"2026-09-04T00:25:51+01:00","source_country":"mexico","quotes_note":"not extracted by the join — a restricted-area clause is quoted by a human, never composed"},"posture":"book-freely","fcdo_zones":[{"name":"The city of Tijuana, in Baja California","lvl":3,"posture":"all-but-essential","except":["airside transit through Tijuana airport","the Cross Border Xpress bridge linking the airport across the border","federal toll road 1D and the Via Rápida through Tijuana to the border"]},{"name":"The city of Tecate in Baja California, including roads between Tijuana and Tecate","lvl":3,"posture":"all-but-essential"},{"name":"The state of Chihuahua","lvl":3,"posture":"all-but-essential","except":["the city of Chihuahua","the border crossing in Ciudad Juárez via federal toll road 45","federal toll road 45D between Chihuahua and Ciudad Juárez","the Copper Canyon rail route and the towns immediately on it, including Creel","the road from Creel via San Juanito to San Pedro","state highway 16 from San Pedro to Chihuahua"],"note":"The advisory also covers the areas south-west of road 45D."},{"name":"The state of Sinaloa","lvl":3,"posture":"all-but-essential","except":["the cities of Los Mochis and Mazatlán","road 32 between El Fuerte and Los Mochis","the 15D federal toll road running the length of the state","the Copper Canyon rail route to and from Los Mochis and El Fuerte, and the towns immediately on it"]},{"name":"The state of Tamaulipas","lvl":3,"posture":"all-but-essential","except":["the border crossing at Nuevo Laredo via federal toll road 85D from Monterrey","federal highways 80, 81 and 85 between Tampico, Ciudad Victoria and Magueyes","the area of Tamaulipas south of those highways"]},{"name":"The state of Zacatecas","lvl":3,"posture":"all-but-essential"},{"name":"In Guanajuato: the areas south-west of road 45D","lvl":3,"posture":"all-but-essential","note":"FCDO advises against all but essential travel to the areas south-west of road 45D. (San Miguel de Allende and Guanajuato City sit outside this area.)"},{"name":"The state of Michoacán","lvl":3,"posture":"all-but-essential","except":["the city of Morelia via federal toll roads 15D, 126 and 43","toll road 48D between Morelia and its airport","the town of Pátzcuaro via toll roads 14D and 15 from Morelia, and boat trips on Lake Pátzcuaro","Federal Highway 15D"]},{"na