ar-round; windiest May-Jul","commission":"operator/affiliate 10-15%","wells":["activities"],"wells_basis":"derived from name/blurb/hook","si_all":["ocean"],"shelf_fit":{"adventure":"destination","diveglobal":"destination","ocean":"primary","romance":"destination","tropical":"destination"},"commission_pct_low":10,"commission_pct_high":15,"commission_lane":["operator","affiliate"],"commission_embedded":false,"commission_basis":"band+lane"},{"name":"Washington Slagbaai National Park","status":"future","tier":"essential","price_band":"~$25-60 + $40 nature fee","timing":"Dec-Apr","draw_rank":1,"when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"the rugged northwest — a 4,286-ha park, 4×4 tracks, cliffs, blowholes, salt pans and inland flamingo lakes","si":"adventure","blurb":"the rugged northwest — a 4,286-ha park, 4×4 tracks, cliffs, blowholes, salt pans and inland flamingo lakes","when":"Dec-Apr","commission":"operator/affiliate","wells":["activities"],"wells_basis":"derived from name/blurb/hook","si_all":["adventure"],"shelf_fit":{"adventure":"primary","diveglobal":"destination","ocean":"destination","romance":"destination","tropical":"destination"},"commission_lane":["operator","affiliate"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Flamingos + the sea-turtle nesting shores","status":"future","tier":"essential","price_band":"~$25-70/pp","timing":"year-round; turtles seasonal","draw_rank":1,"hook":"RAMSAR wetlands with resident flamingos, and beaches that nest all four Caribbean sea-turtle species — a genuine wildlife layer beside the reef","si":"adventure","blurb":"RAMSAR wetlands with resident flamingos, and beaches that nest all four Caribbean sea-turtle species — a genuine wildlife layer beside the reef","when":"year-round; turtles seasonal","commission":"operator/affiliate","wells":[],"wells_basis":"text supports no Well — needs a human read","si_all":["adventure","expedition","tropical","wildlife"],"shelf_